import{a as d}from"./shared-CAKwAg2C.js";const c={"LEARN HOW THE INTERNET WORKS":"كيف يعمل الإنترنت","NOW LEARNING":"الدرس الحالي","OSI LAYER":"طبقة OSI","LEARNING PROGRESS":"تقدّم التعلّم",COMPLETE:"مكتمل","IN PROGRESS":"قيد التقدّم","{pct}% complete":"مكتمل بنسبة {pct}%","DESIGNED BY":"تصميم","Dilum Sanjaya on X":"Dilum Sanjaya على X","Layer {n}: {name}":"الطبقة {n}: {name}",Physical:"الطبقة المادية","Data Link":"طبقة ربط البيانات",Network:"طبقة الشبكة",Transport:"طبقة النقل",Session:"طبقة الجلسة",Presentation:"طبقة العرض",Application:"طبقة التطبيقات","OVERVIEW · {n} STEPS":"نظرة عامة · {n} خطوات","STEP {n}/{total} · {title}":"الخطوة {n}/{total} · {title}","LESSON COMPLETE":"اكتمل الدرس",PROTOCOLS:"البروتوكولات",Protocols:"البروتوكولات",Language:"اللغة",Theme:"المظهر","Light mode":"الوضع الفاتح","Dark mode":"الوضع الداكن","INTERNET PROTOCOLS":"بروتوكولات الإنترنت",More:"المزيد","Close the protocol list":"إغلاق قائمة البروتوكولات","Close (Esc)":"إغلاق (Esc)",ALL:"الكل",CORE:"الأساسية",APPLICATION:"التطبيقات",SECURITY:"الأمان",NETWORK:"الشبكة",SEQUENCE:"التسلسل",View:"العرض","Switch view (V)":"تبديل العرض (V)","Network diagram":"مخطط الشبكة","Sequence diagram":"مخطط التسلسل","STEP {n}":"الخطوة {n}","PROTOCOL OVERVIEW":"نظرة عامة","STEP DETAILS":"تفاصيل الخطوة","LESSON SUMMARY":"ملخّص الدرس",OVERVIEW:"البداية",ACTIVE:"نشط","STEP {n} OF {total}":"الخطوة {n} من {total}","PACKET {n} OF {total}":"الحزمة {n} من {total}","PACKETS {from}–{to} OF {total}":"الحزم {from}–{to} من {total}","{n} LOST":"فُقد {n}","1 LOST":"فُقدت واحدة",ENCRYPTED:"مشفّر","LOST ON THE WAY":"فُقدت في الطريق","PACKET FLOW":"تدفّق الحزم","Colour key":"دليل الألوان","Playback speed":"سرعة التشغيل","Previous step (←)":"الخطوة السابقة (→)","Previous step":"الخطوة السابقة","Play / pause (Space)":"تشغيل / إيقاف مؤقت (مسافة)",PLAY:"تشغيل",PAUSE:"إيقاف مؤقت",REPLAY:"مرة أخرى",STEP:"خطوة","One packet at a time":"حزمة واحدة في كل مرة",RESET:"إعادة تعيين",Reset:"إعادة تعيين","Back to the overview (Esc)":"العودة إلى النظرة العامة (Esc)","NO.":"الرقم",TIME:"الوقت",SOURCE:"المصدر",DESTINATION:"الوجهة",PROTOCOL:"البروتوكول",INFO:"المعلومات",SIZE:"الحجم","No packets on the wire yet.":"لا توجد حزم على السلك بعد.",LOST:"مفقودة","Packet inspector":"فاحص الحزم","Previous packet":"الحزمة السابقة","Previous packet (←)":"الحزمة السابقة (→)","Next packet":"الحزمة التالية","Next packet (→)":"الحزمة التالية (←)",Close:"إغلاق","E.G.":"مثال","an example value: it differs in every real capture":"قيمة مثال: تختلف في كل التقاط حقيقي","bytes the lesson can’t show: encrypted, random, or a file’s contents":"بايتات لا يستطيع الدرس عرضها: مشفّرة أو عشوائية أو محتوى ملف",BYTES:"البايتات","{n} in this frame":"{n} في هذا الإطار","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"يمثّل هذا الصف مقاطع TCP عددها {n} تحمل رسالة من {size} بايت؛ والمعروض هو المقطع الأول","This packet was lost on the way":"فُقدت هذه الحزمة في الطريق",Padding:"الحشو","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · تأجير 24 ساعة","2 SEGMENTS":"مقطعان","3 SEGMENTS":"3 مقاطع","3 DATAGRAMS":"3 مخططات بيانات","4 DATAGRAMS":"4 مخططات بيانات","203.0.113.10 IS NOT LOCAL":"203.0.113.10 ليس محليًا","250 QUEUED":"250 في قائمة الانتظار",ANSWER:"الإجابة","APP COVERS THE 20 MS GAP":"التطبيق يغطّي فجوة 20 ms","APP DATA":"بيانات التطبيق","ARP REPLY":"رد ARP","ARP REQUEST":"طلب ARP","ARRIVED WITH TTL 116":"وصلت بقيمة TTL 116","AUTH FAILURE":"فشل AUTH","At QUIT":"عند QUIT","CACHED · TTL 3600 S":"في الذاكرة المؤقتة · TTL 3600 ث","CERTIFICATE VALID":"الشهادة صالحة","CHAIN LEADS TO A TRUSTED ROOT":"السلسلة تنتهي بجذر موثوق","CHANNEL OPEN":"فتح قناة",CONFIRMED:"تم التأكيد","DNS QUERY":"استعلام DNS","DNS REPLY":"رد DNS","DUP ACK":"ACK مكرّر","EACH KEY IS ITS OWN PACKET":"كل مفتاح في حزمة خاصة به",ECHO:"صدى","ECHO REPLY":"رد الصدى","ECHO REQUEST":"طلب الصدى",ENTER:"Enter","FRAME 7 LOST · NOT RESENT":"الإطار 7 مفقود · لا يُعاد إرساله","HOP 2 · 198.51.100.1":"القفزة 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"مفتاح المضيف يطابق known_hosts","IN BOB’S MAILBOX":"في صندوق بريد Bob","IP PACKET":"حزمة IP",MESSAGE:"الرسالة","MESSAGE 1 DELETED":"حُذفت الرسالة 1","NEW MAIL ARRIVED":"وصل بريد جديد","NO IP ADDRESS YET":"لا يوجد عنوان IP بعد","NOT IN CACHE":"ليس في الذاكرة المؤقتة","OFFER KEY":"عرض المفتاح",OUTPUT:"المخرجات","PASSWORD IN PLAIN TEXT":"كلمة المرور نصّ صريح",REFERRAL:"إحالة",REPLY:"رد",RESEND:"إعادة الإرسال","SEGMENT 1 LOST":"المقطع 1 مفقود","SFTP or FTPS":"SFTP أو FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP، أو FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"حُسب السر المشترك",SIGNED:"موقَّع","STILL ON SERVER · \\SEEN":"لا تزال على الخادم · \\Seen",SUCCESS:"نجاح","TIME EXCEEDED":"تجاوز الوقت","TIME=34MS TTL=52":"TIME=34MS TTL=52",UNREACHABLE:"تعذّر الوصول",VERSION:"الإصدار","VOICE 1":"الصوت 1","+OK or -ERR":"+OK أو -ERR",".com Server":"خادم .com",Authoritative:"الخادم المرجعي","Log In":"تسجيل الدخول",Key:"المفتاح",Why:"السبب",End:"النهاية","MACs, in":"MAC، الواردة",Internet:"الإنترنت",Router:"الموجّه","Router 192.168.1.1":"الموجّه 192.168.1.1","Router: 192.168.1.1":"الموجّه: 192.168.1.1",Routers:"الموجّهات",Hardware:"العتاد",Audio:"الصوت",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"ما يظهر",Tickets:"التذاكر","4, 20 bytes":"4، 20 بايت","20–60 bytes":"20–60 بايت","20–60 bytes (IPv4)":"20–60 بايت (IPv4)","8 bytes (TCP: 20+)":"8 بايت (TCP: 20+)","32 bytes (Windows)":"32 بايت (Windows)","1,460 bytes (MSS)":"1,460 بايت (MSS)","78 bytes (seq 1–78)":"78 بايت (seq 1–78)","bytes 1461–2920":"البايتات 1461–2920","text/html, 12.2 KB":"text/html، 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 بايت)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 بايت)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 بايت)، X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 بايت)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 بايت)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 بايت)',"32 bits (IPv4), 128 (IPv6)":"32 بت (IPv4)، 128 (IPv6)","64 → 52 (12 routers)":"64 ← 52 (12 موجّهًا)","52 (64 − 12 routers)":"52 (64 − 12 موجّهًا)","1 (Ethernet)":"1 (إيثرنت)","report.pdf, 4,000 bytes":"report.pdf، 4,000 بايت","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 بايت (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + صوت"},l={"Hypertext Transfer Protocol":"بروتوكول نقل النص التشعبي","HTTP Secure":"HTTP الآمن","Transmission Control Protocol":"بروتوكول التحكم في الإرسال","User Datagram Protocol":"بروتوكول مخططات بيانات المستخدم","Internet Protocol":"بروتوكول الإنترنت","Domain Name System":"نظام أسماء النطاقات","Dynamic Host Configuration":"التهيئة الديناميكية للمضيف","Internet Control Message":"رسائل التحكم في الإنترنت","Simple Mail Transfer Protocol":"بروتوكول نقل البريد البسيط","Post Office Protocol v3":"بروتوكول مكتب البريد v3","Internet Message Access":"الوصول إلى رسائل الإنترنت","File Transfer Protocol":"بروتوكول نقل الملفات","Secure Shell":"الصدفة الآمنة","Transport Layer Security":"أمان طبقة النقل",Internet:"الإنترنت",Client:"العميل",Router:"الموجّه","DNS Resolver":"محلّل DNS","Web Server":"خادم الويب","Root Server":"خادم الجذر",".com TLD Server":"خادم .com (TLD)","Authoritative Server":"الخادم المرجعي","Mail Server":"خادم البريد","Web Communication":"التواصل عبر الويب",Request:"الطلب",Response:"الاستجابة","Data ACKs not shown":"لا تظهر إقرارات ACK للبيانات","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP هو بروتوكول الويب: يطلب العميل موردًا، مثل صفحة HTML، فيرد الخادم برمز حالة وترويسات، وغالبًا بجسم. كل تبادل هو طلب واحد واستجابة واحدة، مكتوبان في HTTP/1.1 نصًّا مقروءًا.",Layer:"الطبقة","Application (Layer 7)":"التطبيقات (الطبقة 7)","Default Port":"المنفذ الافتراضي",Transport:"طبقة النقل","Data Format":"تنسيق البيانات","Text (headers + optional body)":"نص (ترويسات + جسم اختياري)","Common Methods":"الطرائق الشائعة","Defined In":"مُعرَّف في","Page delivered":"وصلت الصفحة","One request, one response":"طلب واحد واستجابة واحدة","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"في أقل من عُشر ثانية، بحث الحاسوب المحمول عن عنوان، وفتح اتصال TCP، وتبادل طلب HTTP واحدًا واستجابة واحدة، وكان ذلك كله مقروءًا لأي أحد على المسار. اضغط «مرة أخرى» لمشاهدته من جديد.","Round trips":"الرحلات ذهابًا وإيابًا","Total time":"الوقت الإجمالي","Page size":"حجم الصفحة","Sent as 9 TCP segments":"أُرسلت في 9 مقاطع TCP","Client Request":"طلب العميل","Browser prepares the request":"المتصفح يجهّز الطلب","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"تفتح http://www.example.com. سيرسل المتصفح طلب GET، لكن الحزم تُرسل إلى عناوين IP لا إلى الأسماء، لذا يحتاج أولًا إلى عنوان الخادم. (تجرّب المتصفحات اليوم https:// أولًا؛ وهذه هي النسخة غير المشفّرة.)",Method:"الطريقة","Next hop":"القفزة التالية","Router 192.168.1.1":"الموجّه 192.168.1.1","DNS Resolution":"تحليل DNS","Finds the server’s IP address":"يجد عنوان IP للخادم","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"يسأل الحاسوب المحمول خادم DNS الذي حصل عليه من DHCP، وهو 8.8.8.8، عن عنوان www.example.com. يذهب الاستعلام عبر UDP إلى المنفذ 53، والإجابة سجل A يحمل عنوان IPv4. (في شبكة تدعم IPv6 كان سيطلب أيضًا سجل AAAA.)",Resolver:"المحلّل","8.8.8.8 (had it cached)":"8.8.8.8 (كان في الذاكرة المؤقتة)","UDP, port 53":"UDP، المنفذ 53",Answer:"الإجابة","TCP Connection":"اتصال TCP","Establishes a reliable link":"ينشئ اتصالًا موثوقًا","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"يعمل HTTP فوق TCP. قبل انتقال أي بيانات من الصفحة، يفتح الحاسوب المحمول والخادم اتصالًا بالمنفذ 80 عبر مصافحة ثلاثية: SYN، ثم SYN-ACK، ثم ACK.","Server port":"منفذ الخادم","Client port":"منفذ العميل",Handshake:"المصافحة","HTTP Exchange":"تبادل HTTP","Request and response messages":"رسائل الطلب والاستجابة","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"يرسل المتصفح طلب GET مع ترويسة Host. ويرد الخادم بـ 200 OK وفي الجسم صفحة HTML حجمها 12.2 KB، وهي أكبر من أن تتسع لحزمة واحدة، لذا يقسمها TCP إلى 9 مقاطع لا يتجاوز كل منها 1460 بايت (رُسمت هنا كمقطع واحد).",Status:"الحالة",Body:"الجسم","Sent as":"طريقة الإرسال","12.2 KB in 9 segments":"12.2 KB في 9 مقاطع","Page Rendering":"عرض الصفحة","Browser displays the content":"المتصفح يعرض المحتوى","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"يحلل المتصفح HTML ويرسم الصفحة. وكل ملف CSS أو صورة أو نص برمجي مرتبط سيبدأ طلبات أخرى مثل هذا تمامًا، معيدًا استخدام الاتصال المفتوح حيثما أمكن.",Document:"المستند",Connection:"الاتصال","Kept open for reuse":"يبقى مفتوحًا لإعادة الاستخدام","Seen on the laptop’s home network":"كما رُصدت على الشبكة المنزلية للحاسوب المحمول",Destination:"الوجهة","The router: anything beyond the home network goes to it first.":"الموجّه: كل ما يتجاوز الشبكة المنزلية يذهب إليه أولًا.",Source:"المصدر","The laptop’s network card.":"بطاقة الشبكة في الحاسوب المحمول.",Type:"النوع","What the frame carries.":"ما يحمله الإطار.","Version, header length":"الإصدار، طول الترويسة","IPv4, with no options.":"IPv4، بلا خيارات.","Priority and congestion marks; 0 means ordinary traffic.":"علامات الأولوية والازدحام؛ 0 تعني حركة مرور عادية.","Total length":"الطول الكلي","This header and everything inside it.":"هذه الترويسة وكل ما بداخلها.",Identification:"المعرّف","Lets the receiver reassemble the pieces if the packet gets split.":"يتيح للمستقبِل إعادة تجميع الأجزاء إن قُسمت الحزمة.",Flags:"الأعلام",none:"لا شيء","Routers may split it if a link is too small.":"يجوز للموجّهات تقسيمها إن كان أحد الروابط صغيرًا جدًا.","Time to live":"مدة البقاء","Windows starts at 128.":"يبدأ Windows من 128.",Protocol:"البروتوكول","Header checksum":"مجموع تحقق الترويسة","Covers this header only; every router recomputes it after lowering the TTL.":"يغطي هذه الترويسة فقط؛ ويعيد كل موجّه حسابه بعد إنقاص TTL.","Source port":"منفذ المصدر","Destination port":"منفذ الوجهة",Length:"الطول","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"ترويسة UDP والبيانات. هذا كل ما في UDP: لا ترقيم ولا إقرارات.",Checksum:"مجموع التحقق","Covers the header, the data and the IP addresses.":"يغطي الترويسة والبيانات وعناوين IP.","Transaction ID":"معرّف المعاملة","Picked at random; the answer must carry the same one.":"يُختار عشوائيًا؛ ويجب أن تحمل الإجابة القيمة نفسها.","0x0100: query, RD (recursion desired)":"0x0100: استعلام، RD (العودية مطلوبة)",Questions:"الأسئلة",Answers:"الإجابات","Authority records":"سجلات السلطة","Additional records":"سجلات إضافية",Question:"السؤال","www.example.com, type A, class IN":"www.example.com، النوع A، الفئة IN","The laptop.":"الحاسوب المحمول.","The router’s side facing the home network.":"جهة الموجّه المواجهة للشبكة المنزلية.","Started at 128; 10 routers on the way each took 1.":"بدأت من 128؛ وأنقصها كل موجّه من الموجّهات الـ 10 على الطريق بمقدار 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: استجابة، RD (العودية مطلوبة)، RA (العودية متاحة)","DF (don’t fragment)":"DF (لا تُجزّأ)","Routers must not split it; if it’s too big they report back instead.":"لا يجوز للموجّهات تقسيمها؛ وإن كانت كبيرة جدًا فإنها تُبلغ بذلك بدلًا من تقسيمها.","Picked by the laptop’s system for this connection.":"اختاره نظام الحاسوب المحمول لهذا الاتصال.","Sequence number":"رقم التسلسل","This side’s starting number. Shown as 0; the real one is random.":"رقم البداية لهذا الطرف. يظهر 0؛ أما الرقم الحقيقي فعشوائي.","Real sequence number":"رقم التسلسل الحقيقي",Acknowledgment:"رقم الإقرار","0 (not used yet)":"0 (غير مستخدم بعد)","A first SYN has nothing to acknowledge.":"ليس لدى أول SYN ما يُقرّ به.","Header length":"طول الترويسة","20 bytes, plus 12 of options.":"20 بايت، إضافةً إلى 12 للخيارات.",Window:"النافذة","How much more data this side can take right now.":"مقدار البيانات الإضافية التي يستطيع هذا الطرف استقبالها الآن.","Covers the header, the data and the IP addresses, so damage is caught.":"يغطي الترويسة والبيانات وعناوين IP، فيُكتشف أي تلف.","Urgent pointer":"مؤشر الإلحاح",Options:"الخيارات","Maximum segment size":"الحد الأقصى لحجم المقطع","The most data this side wants in one segment.":"أكبر قدر من البيانات يريده هذا الطرف في مقطع واحد.","Spacing, so the next option lines up.":"فراغ لضبط موضع الخيار التالي.","Window scale":"مقياس النافذة","Window values are multiplied by this, so windows can be larger than 64 KB.":"تُضرب قيم النافذة في هذا الرقم، فيمكن أن تصبح النوافذ أكبر من 64 KB.","SACK permitted":"السماح بـ SACK",yes:"نعم","This side understands selective acknowledgements.":"هذا الطرف يفهم الإقرارات الانتقائية.","Started at 64; 12 routers on the way each took 1.":"بدأت من 64؛ وأنقصها كل موجّه من الموجّهات الـ 12 على الطريق بمقدار 1.","The next byte this side expects: everything before it has arrived.":"البايت التالي الذي ينتظره هذا الطرف: كل ما قبله قد وصل.","Position of this segment’s first byte, counted from this side’s SYN.":"موضع أول بايت في هذا المقطع، محسوبًا من SYN هذا الطرف.",Padding:"الحشو","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"لا تقل إطارات إيثرنت عن 60 بايت (64 مع مجموع التحقق الذي تضيفه البطاقة)، لذا تُحشى الإطارات القصيرة.",Text:"النص","covers bytes not shown here":"يشمل بايتات غير معروضة هنا","12,500 bytes: the HTML page":"12,500 بايت: صفحة HTML","The page itself; its contents are not part of the lesson.":"الصفحة نفسها؛ ومحتواها ليس جزءًا من الدرس.","Secure Web":"الويب الآمن","TLS handshake":"مصافحة TLS","HTTP request":"طلب HTTP","HTTP response":"استجابة HTTP","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS هو HTTP المُرسل عبر اتصال TLS مشفّر. يثبت TLS بشهادةٍ أن الخادم هو من يدّعي أنه هو، ويتفق على مفاتيح تشفير جديدة، ثم يحمي كل طلب واستجابة من القراءة أو التعديل في الطريق.","Application (HTTP over TLS)":"التطبيقات (HTTP فوق TLS)",Security:"الأمان","TLS 1.3 (1.2 still common)":"TLS 1.3 (لا يزال 1.2 شائعًا)",Proves:"ما يثبته","Server identity (certificate)":"هوية الخادم (الشهادة)","Secure page delivered":"وصلت الصفحة الآمنة","Encrypted, except the lookup":"مشفّر، باستثناء البحث عن العنوان","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"بحث المتصفح عن العنوان عبر DNS غير مشفّر، وفتح اتصال TCP، وتحقق من شهادة الخادم واتفق على المفاتيح في رحلة واحدة ذهابًا وإيابًا. وانتقل كل بايت من HTTP بعد ذلك مشفّرًا. اضغط «مرة أخرى» لمشاهدته من جديد.",Cipher:"التشفير","Still visible":"ما يزال ظاهرًا","IPs, server name, sizes":"عناوين IP، اسم الخادم، الأحجام","Secure Request":"طلب آمن","Browser asks for https://":"المتصفح يطلب https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"تكتب https://www.example.com. حرف «s» يطلب من المتصفح حماية الاتصال بـ TLS، على المنفذ 443 افتراضيًا. وقبل أن يتصل أصلًا، لا يزال عليه أن يجد عنوان IP للخادم.",Port:"المنفذ","DNS Lookup":"البحث في DNS","Same lookup as HTTP, not encrypted":"البحث نفسه كما في HTTP، غير مشفّر","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"البحث مطابق تمامًا لما في HTTP العادي: استعلام إلى 8.8.8.8 عبر UDP على المنفذ 53. وهو غير مشفّر، لذا يستطيع أي أحد على المسار أن يرى الاسم الذي سألت عنه، ما لم يستخدم المتصفح DNS over HTTPS.",Encrypted:"التشفير","No (plain DNS)":"لا (DNS عادي)","TCP Handshake":"مصافحة TCP","Opens a connection to port 443":"يفتح اتصالًا بالمنفذ 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"يعمل TLS فوق TCP، لذا تأتي المصافحة الثلاثية نفسها أولًا، وهذه المرة إلى المنفذ 443. لا شيء مشفّر بعد.","TLS Handshake":"مصافحة TLS","Agrees on keys, checks the certificate":"يتفق على المفاتيح ويتحقق من الشهادة","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"يعرض المتصفح خوارزميات التشفير وحصص المفاتيح، ومنها حصة هجينة مقاومة للحوسبة الكمّية. يختارها الخادم ويرسل حصته، ثم شهادته وقد صارت مشفّرة. ويتحقق المتصفح منها مقابل الجهات التي يثق بها.",Version:"الإصدار","Key exchange":"تبادل المفاتيح","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (هجين)","Server name":"اسم الخادم","Sent in clear (SNI)":"يُرسل دون تشفير (SNI)","key shares: hybrid + x25519":"حصص المفاتيح: هجينة + x25519","cipher: AES_128_GCM_SHA256":"التشفير: AES_128_GCM_SHA256","then encrypted: cert, Finished":"ثم مشفّر: الشهادة، Finished","handshake complete (encrypted)":"اكتملت المصافحة (مشفّرة)","Encrypted Exchange":"تبادل مشفّر","HTTP inside TLS records":"HTTP داخل سجلات TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET و200 OK هما رسالتا HTTP نفسيهما كما من قبل، لكنهما مختومتان في سجلات TLS تبدو على السلك «بيانات تطبيق» عشوائية. ويسلّم الخادم أيضًا تذكرتي جلسة، فتستطيع الزيارة اللاحقة تخطي جزء من المصافحة.",Inside:"في الداخل","GET / and 200 OK":"GET / و200 OK",Tickets:"التذاكر","2, for faster reconnects":"2، لإعادة اتصال أسرع","inside: GET / HTTP/1.1":"في الداخل: GET / HTTP/1.1","outside: encrypted bytes":"في الخارج: بايتات مشفّرة","inside: HTTP/1.1 200 OK":"في الداخل: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"في الخارج: 12.9 KB، 9 مقاطع","Browser shows the padlock":"المتصفح يعرض القفل","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"يفك المتصفح تشفير الاستجابة، ويرسم الصفحة ويعرض قفلًا: الاتصال خاص، والخادم أثبت هويته. وتطلب منه ترويسة Strict-Transport-Security استخدام HTTPS لهذا الموقع من الآن فصاعدًا.",Remembers:"يتذكّر","HTTPS only (HSTS), 1 year":"HTTPS فقط (HSTS)، سنة واحدة","Server Hello + encrypted handshake, 3 segments":"Server Hello + مصافحة مشفّرة، 3 مقاطع","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec، Finished (مشفّر)","Application Data (HTTP request)":"Application Data (طلب HTTP)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (مشفّر)","Application Data (HTTP response), 9 segments":"Application Data (استجابة HTTP)، 9 مقاطع",Record:"السجل","Content type":"نوع المحتوى","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"يذكر سجل Client Hello الإصدار TLS 1.0 كي تمرّره الأجهزة الوسيطة القديمة؛ أما الإصدارات الحقيقية فتُعرض في الداخل.","Handshake type":"نوع المصافحة",Contents:"المحتويات","Everything the browser supports. Browsers vary a few details from one connection to the next.":"كل ما يدعمه المتصفح. وتغيّر المتصفحات بعض التفاصيل من اتصال إلى آخر.","Server name (SNI)":"اسم الخادم (SNI)","Versions offered":"الإصدارات المعروضة","Key shares":"حصص المفاتيح","App protocols (ALPN)":"بروتوكولات التطبيق (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"تذكر سجلات TLS 1.3 الإصدار 1.2 من الخارج، من أجل التوافق.","The server’s choices and its half of the hybrid key exchange.":"اختيارات الخادم ونصيبه من تبادل المفاتيح الهجين.","Cipher suite":"مجموعة التشفير","Key share":"حصة المفتاح","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"لا عمل لها في TLS 1.3؛ تُرسل كي ترى الأجهزة الوسيطة مصافحة مألوفة.","Every encrypted record says Application Data on the outside; the real type is inside.":"كل سجل مشفّر يذكر Application Data من الخارج؛ أما النوع الحقيقي ففي الداخل.","Encrypted data":"بيانات مشفّرة","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"نص مشفّر ينتهي بوسم من 16 بايت يكشف أي تغيير. لا يقرؤه إلا الطرفان.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1)، Certificate (السلسلة)، Certificate Verify (التوقيع)، Finished","Finished: a check value over the whole handshake":"Finished: قيمة تحقق تشمل المصافحة كلها","The HTTP request":"طلب HTTP","New Session Ticket: lets a later visit resume":"New Session Ticket: يتيح لزيارة لاحقة استئناف الجلسة","The HTTP response, then the 12,500-byte page":"استجابة HTTP، ثم الصفحة ذات 12,500 بايت","Reliable Delivery":"التسليم الموثوق","Handshake and ACKs":"المصافحة وإقرارات ACK","Data from laptop":"بيانات من الحاسوب المحمول","Data from server":"بيانات من الخادم","Closing (FIN)":"الإغلاق (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"يحوّل TCP توصيل الحزم «بأفضل جهد» في الإنترنت إلى تيار بايتات موثوق ومرتّب. فهو يرقّم كل بايت، ويُقرّ بما يصل، ويعيد إرسال ما يضيع، وينظّم سرعة المرسل كي لا يُغرق الطرف الآخر ولا الشبكة.","Transport (Layer 4)":"النقل (الطبقة 4)","Three-way handshake":"المصافحة الثلاثية",Reliability:"الموثوقية","Sequence numbers + ACKs":"أرقام التسلسل + ACK",Recovery:"الاستعادة",Retransmission:"إعادة الإرسال",Header:"الترويسة","Connection closed":"أُغلق الاتصال","Every byte accounted for":"كل بايت في الحسبان","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"فتح TCP اتصالًا، ورقّم كل بايت وأقرّ به، ولاحظ فجوة فأعاد إرسال المقطع المفقود وحده، ثم أغلق الاتجاهين بنظافة. تسلّم curl كل بايت بالترتيب ولم يرَ الفقد قط. اضغط «مرة أخرى» لمشاهدته من جديد.",Segments:"المقاطع","14 (1 lost, 1 resent)":"14 (فُقد 1، وأُعيد إرسال 1)","Bytes delivered":"البايتات المُسلَّمة","78 up, 2,920 down":"78 صادرة، 2,920 واردة","Loss found by":"اكتُشف الفقد عبر","Duplicate ACK + SACK":"ACK مكرر + SACK","Open Connection":"فتح الاتصال","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"يعرف curl عنوان الخادم مسبقًا. وقبل أن تنتقل أي بيانات، يختار كل طرف رقم تسلسل ابتدائيًا ويؤكده: SYN، ثم SYN-ACK، ثم ACK. الأرقام هنا نسبية؛ أما الحقيقية فتبدأ من قيمة عشوائية.",Server:"الخادم","203.0.113.10, port 80":"203.0.113.10، المنفذ 80","Send Data":"إرسال البيانات","Every byte is numbered":"لكل بايت رقم","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"يرسل curl طلب HTTP الخاص به المكوّن من 78 بايت: البايتات من 1 إلى 78. ورقم ACK لدى الخادم، 79، هو البايت التالي الذي ينتظره، أي أن كل ما قبله قد وصل.",Sent:"أُرسل","79 = next byte expected":"79 = البايت التالي المنتظر","Two Segments Back":"مقطعان عائدان","One of them is lost":"أحدهما يضيع","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"يجيب الخادم بـ 2,920 بايت: مقطعين كاملين من 1,460 بايت، وهو أقصى ما تتسع له حزمة واحدة هنا، أُرسلا متتاليين. يسقط الأول في مكان ما على الإنترنت؛ ويصل الثاني.","Segment 1":"المقطع 1","bytes 1–1460 (lost)":"البايتات 1–1460 (مفقودة)","Segment 2":"المقطع 2","Segment size":"حجم المقطع","seq=1 and seq=1461":"seq=1 و seq=1461","the first is lost":"الأول يضيع","A Gap Is Noticed":"رصد فجوة","Duplicate ACK with SACK":"ACK مكرر مع SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"تصل البايتات 1461–2920، لكن 1–1460 لم تصل قط. لا يستطيع ACK أن يحسب إلا البايتات المستلمة بالترتيب، لذا يكرر الحاسوب المحمول ACK 1 فورًا ويضيف كتلة SACK تقول إن لديه 1461–2920 بالفعل.","1 (still waiting for byte 1)":"1 (ما يزال ينتظر البايت 1)","holds bytes 1461–2920":"لديه البايتات 1461–2920","At once, not delayed":"فورًا، دون تأخير","sack: has 1461–2920":"sack: لديه 1461–2920","Resend the Gap":"إعادة إرسال الفجوة","Only the missing bytes":"البايتات المفقودة فقط","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"يخبر SACK الخادم بما فُقد تحديدًا، فيعيد إرسال المقطع 1 وحده، ويُقرّ الحاسوب المحمول بكل شيء. ولو لم يعد أي ACK إطلاقًا، لتولّت المؤقّتات الأمر: أولًا حزمة استكشاف بعد نحو رحلتين ذهابًا وإيابًا، ثم مهلة إعادة الإرسال (200 ms على الأقل في Linux).",Resent:"أُعيد إرساله","bytes 1–1460 only":"البايتات 1–1460 فقط","Next ACK":"ACK التالي","2921 (everything)":"2921 (كل شيء)","curl saw":"ما رآه curl","Every byte, in order":"كل بايت، بالترتيب","just the missing segment":"المقطع المفقود فقط","Close Connection":"إغلاق الاتصال","Each side says goodbye":"كل طرف يودّع","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"انتهى curl، فيُغلق الاتصال. يُغلَق كل اتجاه على حدة: يرسل الحاسوب المحمول FIN فيُقرّ به الخادم، ثم يرسل الخادم FIN الخاص به فيُقرّ به الحاسوب المحمول. ويحتفظ الحاسوب المحمول بتفاصيل الاتصال فترةً (TIME-WAIT).","Closed by":"أُغلق بواسطة","A FIN from each side":"FIN من كل طرف",Order:"الترتيب",Then:"ثم","Laptop waits (TIME-WAIT)":"الحاسوب المحمول ينتظر (TIME-WAIT)",Data:"البيانات","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 بايت: استجابة HTTP، البايتات 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 بايت: استجابة HTTP، البايتات 1461–2920","has 1461–2920":"لديه 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"بايتات وصلت بعد الفجوة، فلا يلزم إلا إعادة إرسال الفجوة.","Fast Datagrams":"مخططات بيانات سريعة","Your voice":"صوتك","Their voice":"صوت محدّثك","Media Server":"خادم الوسائط","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"يرسل UDP البيانات في حزم مستقلة تُسمّى مخططات البيانات (datagrams)، بلا اتصال ولا إقرارات ولا إعادة إرسال. وهذا يبقيه سريعًا وخفيفًا: مناسبًا للصوت والفيديو والألعاب وDNS، حيث الإجابة المتأخرة أسوأ من الإجابة المفقودة.",None:"لا يوجد","None (no ACKs, no resends)":"لا يوجد (لا إقرارات ولا إعادة إرسال)",Ordering:"الترتيب","Not guaranteed":"غير مضمون","Call keeps flowing":"المكالمة مستمرة","Fast, simple, no guarantees":"سريع، بسيط، بلا ضمانات","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"بدأ الصوت مع أول حزمة، وانتقل كل مخطط بيانات وحده، أما الذي فُقد فقد ضاع ببساطة: لم يلاحظ UDP ذلك قط. غطّى التطبيق الفجوة واستمرت المكالمة. اضغط «مرة أخرى» لمشاهدته من جديد.",Datagrams:"مخططات البيانات","11 (1 lost, never resent)":"11 (فُقد 1، ولم يُعَد إرساله)","Setup time":"وقت الإعداد","0 ms (no handshake)":"0 ms (بلا مصافحة)",Shown:"المعروض","The first 0.2 s of a call":"أول 0.2 s من مكالمة","Send Right Away":"الإرسال فورًا","No handshake, data goes first":"بلا مصافحة، البيانات أولًا","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"يعرف تطبيق المكالمات عنوان خادم الوسائط ومنفذه منذ تسجيل الدخول. ولا يفتح اتصالًا: فأول مخطط بيانات يحمل بالفعل 20 ms من صوتك، خلف ترويسة UDP من 8 بايت.",Setup:"الإعداد",Ports:"المنافذ","92 B of audio, no setup":"92 B من الصوت، بلا إعداد","A Stream of Datagrams":"تيار من مخططات البيانات","One every 20 ms, each on its own":"واحد كل 20 ms، كلٌّ مستقل","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"يواصل التطبيق إرسال مخطط بيانات كل 20 ms. كل واحد قائم بذاته، بترويسته الخاصة ولا صلة له بغيره. لا يرقّمها UDP، ولا يعود شيء لتأكيد وصولها.",Rate:"المعدّل","1 datagram / 20 ms":"1 مخطط بيانات / 20 ms",Numbering:"الترقيم","None in UDP itself":"لا يوجد في UDP نفسه",Confirmation:"التأكيد","None (no ACKs)":"لا يوجد (لا إقرارات)","voice frames 2–5":"الإطارات الصوتية 2–5","each with its own 8-byte header":"لكلٍّ ترويسته من 8 بايت","Lost on the Way":"فُقد في الطريق","Nobody resends it":"لا أحد يعيد إرساله","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"يسقط الإطار 7 في مكان ما على الإنترنت. لا يطلبه خادم الوسائط أبدًا، ولا يخبر UDP الحاسوب المحمول بشيء: فلا إقرارات يمكن أن تغيب. وتصل مخططات البيانات التي بعده كالمعتاد.",Lost:"المفقود","Voice frame 7":"الإطار الصوتي 7","Never (no ACKs)":"أبدًا (لا إقرارات)",Missing:"الناقص","20 ms of audio":"20 ms من الصوت","voice frames 6–8":"الإطارات الصوتية 6–8","frame 7 is lost":"الإطار 7 يضيع","Replies Come Back":"الردود تعود","The other voice comes back":"الصوت الآخر يعود","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"يصل صوت الطرف الآخر بالطريقة نفسها، مخططاتِ بيانات منفصلة مُرسلة إلى المنفذ 50000. وتدخل لأن موجّهك تذكّر المنفذ الصادر حين ترجم عنوانك (NAT).",Direction:"الاتجاه","Independent of ours":"مستقل عن اتجاهنا","Through NAT":"عبر NAT","Router remembers the port":"الموجّه يتذكّر المنفذ","the other person’s voice":"صوت الطرف الآخر","sent to port 50000":"مُرسل إلى المنفذ 50000","The App Decides":"التطبيق يقرّر","Reliability is up to the app":"الموثوقية مسؤولية التطبيق","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"يرقّم تطبيق المكالمات إطاراته بنفسه (وهذا ما يفعله RTP)، فيرى أن الإطار 7 مفقود ويُخفي فجوة الـ 20 ms بدلًا من الانتظار. فانتظار إعادة الإرسال سيجعل المكالمة كلها تتأخر.","App’s job (e.g. RTP)":"مهمة التطبيق (مثل RTP)",Loss:"الفقد","Hidden by the app":"يخفيه التطبيق","Also on UDP":"أيضًا عبر UDP","DNS, games, QUIC":"DNS، الألعاب، QUIC","Version etc.":"الإصدار وغيره","2, no padding, no extension, no CSRCs":"2، بلا حشو، بلا امتداد، بلا CSRC","Marker, payload type":"العلامة، نوع الحمولة","1, 111 (Opus, agreed when the call was set up)":"1، 111 (Opus، اتُّفق عليه عند إعداد المكالمة)","Counts up by one per packet, so the app can spot a missing or late one.":"يزيد واحدًا مع كل حزمة، فيستطيع التطبيق رصد حزمة مفقودة أو متأخرة.",Timestamp:"الطابع الزمني","Audio clock at 48,000 per second: +960 per 20 ms frame.":"ساعة صوت بمعدل 48,000 في الثانية: +960 لكل إطار من 20 ms.","Identifies this audio stream.":"يعرّف تيار الصوت هذا.",Audio:"الصوت","80 bytes of Opus audio (20 ms)":"80 بايت من صوت Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0، 111 (Opus، اتُّفق عليه عند إعداد المكالمة)","Addressing & Routing":"العنونة والتوجيه","Outgoing packet":"الحزمة الصادرة",Reply:"الرد","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"يمنح IP كل جهاز عنوانًا وينقل الحزم من شبكة إلى أخرى. ولا ينظر كل موجّه إلا إلى عنوان الوجهة ليختار القفزة التالية. يعمل IP «بأفضل جهد»: فلا يعد بالتسليم ولا بالترتيب. ويضيف TCP ذلك فوقه.","Network (Layer 3)":"الشبكة (الطبقة 3)",Address:"العنوان","Lowered by 1 at each router":"ينقص 1 عند كل موجّه",Delivery:"التسليم","Best effort":"بأفضل جهد","There and back":"ذهابًا وإيابًا","Twelve routers each way":"اثنا عشر موجّهًا في كل اتجاه","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"أرسل الحاسوب المحمول الحزمة إلى موجّهه، فوضع فيها عنوانه العام. ومرّرها اثنا عشر موجّهًا في المجموع بالاعتماد على عنوان الوجهة وحده، ووجد الرد طريقه عائدًا بالطريقة نفسها. اضغط «مرة أخرى» لمشاهدته من جديد.",Routers:"الموجّهات","12 each way (1 home + 11)":"12 في كل اتجاه (1 منزلي + 11)","TTL at server":"TTL عند الخادم","116 (sent with 128)":"116 (أُرسلت بـ 128)","Rewritten by NAT":"يعيد NAT كتابته","Source out, destination back":"المصدر ذهابًا، والوجهة إيابًا","IPv4 (IPv6 works alike)":"IPv4 (ويعمل IPv6 بالمثل)","Local or Not?":"محلي أم لا؟","Compare the address with the subnet":"مقارنة العنوان بالشبكة الفرعية","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"عنوان الحاسوب المحمول 192.168.1.10 بقناع /24، لذا تمتد شبكته من 192.168.1.0 إلى 192.168.1.255. والخادم، 203.0.113.10، خارج هذا النطاق، لذا يجب أن تذهب الحزمة إلى البوابة الافتراضية: الموجّه المنزلي.",Laptop:"الحاسوب المحمول","Local range":"النطاق المحلي",Gateway:"البوابة","Find the Router":"العثور على الموجّه","ARP turns an IP into a MAC":"يحوّل ARP عنوان IP إلى MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"تُسلَّم الإطارات على الشبكة المحلية حسب عنوان MAC. فإن لم يكن عنوان MAC للموجّه في ذاكرة ARP المؤقتة للحاسوب المحمول، يبث سؤال «من لديه 192.168.1.1؟» فيجيب الموجّه بعنوان MAC الخاص به.",Asks:"يسأل","Who has 192.168.1.1?":"من لديه 192.168.1.1؟","Sent to":"مُرسل إلى","Everyone (broadcast)":"الجميع (بث)",Learns:"يتعلّم","Router’s MAC address":"عنوان MAC للموجّه","who has 192.168.1.1?":"من لديه 192.168.1.1؟","tell 192.168.1.10":"أخبر 192.168.1.10","Send the Packet":"إرسال الحزمة","Addresses, TTL and protocol":"العناوين، TTL والبروتوكول","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"تحمل ترويسة IP عنوانَي المصدر والوجهة، وقيمة TTL، والبروتوكول الذي بداخلها. وهي هنا تحمل TCP SYN إلى المنفذ 443. يبدأ Windows قيمة TTL من 128 (ويستخدم Linux وmacOS القيمة 64).","From → to":"من ← إلى","TTL 128 · protocol TCP":"TTL 128 · البروتوكول TCP","NAT, Then Hop by Hop":"NAT، ثم قفزة بعد قفزة","The router rewrites and forwards":"الموجّه يعيد الكتابة ويمرّر","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"يستبدل الموجّه بالمصدر الخاص عنوانه العام 198.51.100.7 (وهنا المنفذ 40112 بدل 52344)، ويسجّل هذا الربط، ويُنقص TTL إلى 127. ثم يختار كل واحد من 11 موجّهًا على الإنترنت القفزة التالية حسب الوجهة ويُنقص TTL مجددًا.","New source":"المصدر الجديد","Leaves home":"عند مغادرة المنزل","At the server":"عند الخادم","TTL 116 (11 more hops)":"TTL 116 (11 قفزة إضافية)","TTL 127 · after NAT":"TTL 127 · بعد NAT","The Reply Comes Back":"الرد يعود","NAT translates it for the laptop":"يترجمه NAT للحاسوب المحمول","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"يجيب الخادم العنوان الذي رآه، 198.51.100.7:40112. يبحث الموجّه عنه في جدول NAT، ويعيد كتابة الوجهة إلى 192.168.1.10:52344 ويمرّره. بدأ الرد بـ TTL 64 ويصل بـ 52.","Delivered to":"سُلّم إلى","TTL 52 · after NAT":"TTL 52 · بعد NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (بعد NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (بعد NAT)","ARP request · 28 bytes":"طلب ARP · 28 بايت","Broadcast: every device on the network receives it.":"بث: يستقبله كل جهاز على الشبكة.","The sender’s network card.":"بطاقة الشبكة لدى المرسل.","Hardware type":"نوع العتاد","Protocol type":"نوع البروتوكول","Address sizes":"أحجام العناوين",Operation:"العملية","1 (request: who has …?)":"1 (طلب: من لديه …؟)","Sender MAC":"MAC المرسل","Sender IP":"IP المرسل","Target MAC":"MAC الهدف","All zeros: this is what the request wants to find out.":"أصفار كلها: هذا ما يريد الطلب معرفته.","Target IP":"IP الهدف","ARP reply · 28 bytes":"رد ARP · 28 بايت","Straight back to the device that asked.":"مباشرةً إلى الجهاز الذي سأل.","2 (reply: … is at …)":"2 (رد: … موجود عند …)","Seen as it leaves the router’s internet side":"كما رُصدت عند خروجها من جهة الموجّه المواجهة للإنترنت","The internet provider’s router, the next hop.":"موجّه مزوّد الإنترنت، القفزة التالية.","The router’s internet-facing port.":"منفذ الموجّه المواجه للإنترنت.","As sent: this system starts at 64.":"كما أُرسلت: يبدأ هذا النظام من 64.","The router’s NAT swapped in its own port for the laptop’s.":"استبدل NAT في الموجّه بمنفذ الحاسوب المحمول منفذًا خاصًا به.","The sender’s next router; each hop puts the packet in a new frame.":"الموجّه التالي للمرسل؛ كل قفزة تضع الحزمة في إطار جديد.","Name Resolution":"تحليل الأسماء",Query:"الاستعلام",Referral:"الإحالة","DNSSEC not requested here":"لم يُطلب DNSSEC هنا","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"يحوّل DNS أسماءً مثل www.example.com إلى عناوين IP التي تستخدمها الحواسيب للوصول إلى بعضها. لا يعرف خادم واحد كل الأسماء: فالنظام تسلسل هرمي من الخوادم، وتُخزَّن الإجابات مؤقتًا على الطريق، لذا لا تحتاج معظم عمليات البحث إلى الذهاب بعيدًا.","53, UDP (TCP if large)":"53، UDP (أو TCP إن كبر الحجم)",Turns:"يحوّل","Names into IP addresses":"الأسماء إلى عناوين IP",Hierarchy:"التسلسل الهرمي","Root → TLD → authoritative":"الجذر ← TLD ← المرجعي",Caching:"التخزين المؤقت","For each record’s TTL":"طوال TTL كل سجل","Name resolved":"تم تحليل الاسم","And remembered for an hour":"وحُفظ لمدة ساعة","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"بدءًا من ذاكرة مؤقتة فارغة، انتقل المحلّل من الجذر إلى .com إلى خادم example.com نفسه، ثم أجاب الحاسوب المحمول. وإلى أن تنتهي مدة TTL، يُجاب البحث التالي عن هذا الاسم من الذاكرة المؤقتة مباشرة. اضغط «مرة أخرى» لمشاهدته من جديد.",Queries:"الاستعلامات","4 (laptop 1, resolver 3)":"4 (الحاسوب المحمول 1، المحلّل 3)","Cached for":"مدة التخزين","Ask the Resolver":"سؤال المحلّل","The laptop hands the question off":"الحاسوب المحمول يُحيل السؤال","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"يحتاج المتصفح إلى عنوان IP لـ www.example.com، وليس لديه ولا لدى Windows نسخة مخزّنة منه. فيرسل الحاسوب المحمول سؤالًا واحدًا إلى المحلّل العودي الذي أُعطي له، 8.8.8.8، ويطلب منه إجراء البحث كله (العودية مطلوبة).","www.example.com, type A":"www.example.com، النوع A",Asked:"المسؤول","8.8.8.8 (recursive)":"8.8.8.8 (عودي)","RD (recursion desired)":"RD (العودية مطلوبة)","flags: RD":"الأعلام: RD","Points the way to .com":"يدلّ على طريق .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"الذاكرة المؤقتة للمحلّل فارغة (فقد بدأ للتو)، لذا يبدأ من القمة. لا يعرف خادم الجذر العنوان، لكنه يعرف أي الخوادم تتولى .com فيرد بإحالة. وكثير من المحلّلات ترسل إليه «com» فقط، لا الاسم الكامل.","Root servers":"خوادم الجذر","13 names, 1,000+ anycast sites":"13 اسمًا، 1,000+ موقع anycast","Referral (13 .com servers)":"إحالة (13 خادم .com)","no answer: ask .com":"لا إجابة: اسأل .com","Points the way to example.com":"يدلّ على طريق example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"يسأل المحلّل أحد خوادم .com. وهي أيضًا لا تخزّن عناوين كل المواقع، لكنها تعرف خوادم الأسماء التي يستخدمها كل نطاق .com، لذا فهذا الرد إحالة أخرى، مرفقة بعناوين تلك الخوادم (glue).",Knows:"يعرف","Name servers of .com domains":"خوادم أسماء نطاقات .com","Referral + glue addresses":"إحالة + عناوين glue","no answer: ask example.com":"لا إجابة: اسأل example.com","Gives the actual answer":"يعطي الإجابة الفعلية","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"أخيرًا يسأل المحلّل خادم الأسماء الخاص بـ example.com، الذي يحتفظ بسجلات النطاق. فيجيب بسجل A ويَسِم الرد بأنه مرجعي. ويحدّد مالك النطاق مدة تخزينه المؤقت: هنا 3600 ثانية.","AA (authoritative), TTL 3600":"AA (مرجعي)، TTL 3600","TTL 3600 · flag AA":"TTL 3600 · العلم AA","Answer & Cache":"الإجابة والتخزين","The laptop gets its address":"الحاسوب المحمول يحصل على عنوانه","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"يرسل المحلّل الإجابة إلى الحاسوب المحمول ويحتفظ بنسخة. وطوال الساعة التالية يستطيع الإجابة عن هذا الاسم فورًا، ولهذا لم يستغرق البحث في درس HTTP سوى 24 ms. ويخزّنها الحاسوب المحمول مؤقتًا أيضًا.","RD, RA (recursion available)":"RD، RA (العودية متاحة)","Cached by":"خزّنه","Resolver and laptop":"المحلّل والحاسوب المحمول","flags: RD RA":"الأعلام: RD RA","Referral: com. NS ×13 (with glue)":"إحالة: com. NS ×13 (مع glue)","Referral: example.com. NS ×2 (with glue)":"إحالة: example.com. NS ×2 (مع glue)","Response A 203.0.113.10 (authoritative)":"استجابة A 203.0.113.10 (مرجعية)","As sent: this system starts at 128.":"كما أُرسلت: يبدأ هذا النظام من 128.","0x0000: query":"0x0000: استعلام","UDP size 1232, DNSSEC OK = 0":"حجم UDP 1232، DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"يحدّد الحجم الأقصى لإجابة UDP. لا تُطلب تواقيع DNSSEC هنا لإبقاء الدرس قصيرًا؛ أما المحلّل الذي يتحقق منها مثل 8.8.8.8 فيطلبها.","0x8000: response":"0x8000: استجابة",Authority:"السلطة",Additional:"الإضافية","0x8400: response, AA (authoritative)":"0x8400: استجابة، AA (مرجعية)","Getting an Address":"الحصول على عنوان","From the laptop":"من الحاسوب المحمول","From the DHCP server":"من خادم DHCP","Dynamic Host Configuration Protocol":"بروتوكول التهيئة الديناميكية للمضيف","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"يمنح DHCP الجهاز كل ما يحتاجه لاستخدام شبكة: عنوان IP، وقناع الشبكة الفرعية، والموجّه الذي تمر عبره حركة البيانات، وخوادم DNS التي يسألها. وتُؤجَّر العناوين لمدة محددة وتُجدَّد ما دام الجهاز على الشبكة.","UDP 67 (server), 68 (client)":"UDP 67 (الخادم)، 68 (العميل)","Hands out":"يوزّع","IP, mask, gateway, DNS":"IP، القناع، البوابة، DNS",Exchange:"التبادل",Lease:"الإيجار","Renewed at half its time":"يُجدَّد في منتصف مدته","On the network":"على الشبكة","Leased, and kept up to date":"مؤجَّر، ويبقى محدَّثًا","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"نقلت أربع رسائل الحاسوب المحمول من انعدام العنوان إلى إعدادات تعمل، وفي منتصف إيجار الـ 24 ساعة جدّده بطلب مباشر إلى الموجّه. اضغط «مرة أخرى» لمشاهدته من جديد.",Messages:"الرسائل","4 to join, 2 per renewal":"4 للانضمام، و2 لكل تجديد","24 h, renewed at 12 h":"24 h، يُجدَّد عند 12 h","No Address Yet":"لا عنوان بعد","The laptop joins the network":"الحاسوب المحمول ينضم إلى الشبكة","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"اتصل الحاسوب المحمول للتو. لديه عنوان MAC مدمج، لكن لا عنوان IP ولا بوابة ولا خادم DNS، لذا لا يستطيع بعدُ التواصل مع أي شيء خارج شبكته. فيطلبها عبر DHCP.","IP address":"عنوان IP","None (uses 0.0.0.0)":"لا يوجد (يستخدم 0.0.0.0)","MAC address":"عنوان MAC",Needs:"يحتاج إلى",Discover:"الاستكشاف","Shout to the whole network":"نداء إلى الشبكة كلها","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"لعدم امتلاكه عنوانًا خاصًا به، يرسل الحاسوب المحمول من 0.0.0.0 إلى عنوان البث 255.255.255.255، فيستقبله كل جهاز على الشبكة المحلية. ولا تجيب إلا خوادم DHCP.",From:"من","0.0.0.0, UDP port 68":"0.0.0.0، منفذ UDP 68","255.255.255.255, port 67":"255.255.255.255، المنفذ 67",Carries:"يحمل","MAC, transaction ID":"MAC، معرّف المعاملة","any DHCP server out there?":"هل من خادم DHCP هنا؟",Offer:"العرض","The router proposes an address":"الموجّه يقترح عنوانًا","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"يختار خادم DHCP في الموجّه عنوانًا شاغرًا ويعرضه مع بقية الإعدادات. ولا يستطيع الحاسوب المحمول استخدام عنوان IP بعد، لذا يذهب العرض مباشرة إلى عنوان MAC الخاص به (وبعض العملاء يطلبون البث بدلًا من ذلك).",Offered:"المعروض","Gateway, DNS":"البوابة، DNS","offer: 192.168.1.10/24":"عرض: 192.168.1.10/24","gateway, DNS, lease 24 h":"البوابة، DNS، إيجار 24 h","Accept, out loud":"قبول على الملأ","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"يطلب الحاسوب المحمول العنوان المعروض، مسمّيًا الخادم الذي اختاره. وهو ما يزال يبث، فيعلم أي خادم DHCP آخر قدّم عرضًا أنه لم يُختر، ويستطيع تحرير عنوانه.",Requests:"يطلب","Chosen server":"الخادم المختار","I’ll take 192.168.1.10":"سآخذ 192.168.1.10","from server 192.168.1.1":"من الخادم 192.168.1.1",Acknowledge:"الإقرار","The address is the laptop’s":"العنوان صار للحاسوب المحمول","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"يؤكد الخادم، فيضبط الحاسوب المحمول عنوانه وقناعه وبوابته وخادم DNS. وتتحقق أنظمة كثيرة أولًا عبر ARP من أن أي جهاز آخر لا يستخدم العنوان بالفعل.","DNS server":"خادم DNS","192.168.1.10 is yours":"192.168.1.10 لك","for 24 hours":"لمدة 24 ساعة",Renew:"التجديد","Halfway through the lease":"في منتصف مدة الإيجار","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"بعد اثنتي عشرة ساعة، انقضى نصف الإيجار. صار للحاسوب المحمول عنوان الآن، لذا يطلب من الموجّه مباشرةً تمديد الإيجار، فيعيده الموجّه إلى 24 ساعة. ولو لم يجب الموجّه، لبثّ الحاسوب طلبه عند 87.5%.",When:"متى","50% of lease (T1 = 12 h)":"50% من الإيجار (T1 = 12 h)","The router (unicast)":"الموجّه (إرسال أحادي)","If unanswered":"إن لم تأتِ إجابة","Broadcast at 87.5% (T2)":"بث عند 87.5% (T2)","renew 192.168.1.10":"تجديد 192.168.1.10","sent straight to 192.168.1.1":"أُرسل مباشرة إلى 192.168.1.1","lease renewed":"جُدّد الإيجار","another 24 hours":"24 ساعة أخرى",Message:"الرسالة","1 (request, from a client)":"1 (طلب، من عميل)",Hardware:"العتاد","Ethernet, 6-byte addresses":"إيثرنت، عناوين من 6 بايت",Hops:"القفزات","Chosen by the client; every reply repeats it.":"يختاره العميل؛ ويكرره كل رد.",Seconds:"الثواني","0x0000 (unicast replies are fine)":"0x0000 (الردود الأحادية مقبولة)","Broadcast flag off: the server may send straight to the client’s MAC address.":"علم البث مطفأ: يجوز للخادم الإرسال مباشرة إلى عنوان MAC للعميل.","Client address":"عنوان العميل","Filled in only when the client already has an address (renewing).":"لا يُملأ إلا إذا كان للعميل عنوان بالفعل (عند التجديد).","Your address":"عنوانك","The address the server is giving out.":"العنوان الذي يمنحه الخادم.","Next server":"الخادم التالي","Relay agent":"وكيل الترحيل","Client MAC":"MAC العميل","Server name, boot file":"اسم الخادم، ملف الإقلاع",empty:"فارغ","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"يَسِم الخيارات التالية بأنها خيارات DHCP.","Message type: 1 (Discover)":"نوع الرسالة: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"معرّف العميل: 01 00:00:5e:00:53:10","Host name: alice-laptop":"اسم المضيف: alice-laptop","Vendor class: MSFT 5.0":"فئة المورّد: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"المعاملات المطلوبة: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (رد، من خادم)","Message type: 2 (Offer)":"نوع الرسالة: 2 (Offer)","Server identifier: 192.168.1.1":"معرّف الخادم: 192.168.1.1","Lease time: 86,400 s (24 h)":"مدة الإيجار: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"وقت التجديد (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"وقت إعادة الربط (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"قناع الشبكة الفرعية: 255.255.255.0","Broadcast address: 192.168.1.255":"عنوان البث: 192.168.1.255","DNS server: 8.8.8.8":"خادم DNS: 8.8.8.8","Message type: 3 (Request)":"نوع الرسالة: 3 (Request)","Requested address: 192.168.1.10":"العنوان المطلوب: 192.168.1.10","Client FQDN: alice-laptop":"FQDN العميل: alice-laptop","Message type: 5 (ACK)":"نوع الرسالة: 5 (ACK)","Network Diagnostics":"تشخيص الشبكة","Ping / probe":"ping / فحص","Echo reply":"رد الصدى","Error report":"تقرير خطأ","Internet Control Message Protocol":"بروتوكول رسائل التحكم في الإنترنت","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP هو الطريقة التي تُبلغ بها الشبكة: موجّه يقول إن وقت حزمة قد نفد، وخادم يقول إن لا شيء يستمع على منفذ ما. وأدوات مثل ping وtraceroute مبنية من هذه الرسائل. وهو ينتقل داخل IP لكنه لا يحمل بيانات تطبيق.","Carried in":"محمول في","IP (protocol 1)":"IP (البروتوكول 1)","A type and a code":"نوع ورمز",Tools:"الأدوات",Often:"غالبًا","Filtered by firewalls":"تحجبه جدران الحماية","The network answered":"الشبكة أجابت","Replies, expiries and errors":"ردود وانتهاء صلاحية وأخطاء","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"قاس طلب صدى الرحلة ذهابًا وإيابًا، وجعلت حزمٌ ذات TTL صغير كل موجّه على المسار يعرّف بنفسه، وأُبلغ عن منفذ مغلق مباشرة. اضغط «مرة أخرى» لمشاهدته من جديد.","Round trip":"الرحلة ذهابًا وإيابًا",Path:"المسار","12 routers, server at hop 13":"12 موجّهًا، والخادم عند القفزة 13","Types used":"الأنواع المستخدمة","8, 0, 11 and 3":"8 و0 و11 و3","Reply TTL":"TTL الرد",Ping:"Ping","Echo request":"طلب الصدى","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"يرسل «ping -n 1 203.0.113.10» طلب صدى ICMP واحدًا (يرسل ping العادي أربعة، بفاصل ثانية): النوع 8، الرمز 0، مع معرّف ورقم تسلسل و32 بايت حشو. ويجيب نظام الخادم بنفسه، دون حاجة إلى تطبيق.","Type, code":"النوع، الرمز","8, 0 (echo request)":"8، 0 (طلب صدى)","type 8 · seq 1":"النوع 8 · seq 1","32 bytes of data":"32 بايت من البيانات","Echo Reply":"رد الصدى","Round-trip time":"زمن الرحلة ذهابًا وإيابًا","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"يعيد الخادم رد صدى، النوع 0، بالمعرّف ورقم التسلسل والبيانات نفسها. ويطبع ping الوقت المستغرق وقيمة TTL التي وصل بها الرد: «bytes=32 time=34ms TTL=52».","0, 0 (echo reply)":"0، 0 (رد صدى)","TTL on arrival":"TTL عند الوصول","type 0 · seq 1":"النوع 0 · seq 1","same 32 bytes back":"الـ 32 بايت نفسها تعود","The first router answers":"الموجّه الأول يجيب","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"يرسل «ping -n 1 -i 1» الطلب نفسه بقيمة TTL تساوي 1. يُنقصها الموجّه المنزلي إلى 0، فيجب أن يُسقط الحزمة، ويعيد رسالة Time Exceeded من عنوانه: «Reply from 192.168.1.1: TTL expired in transit.»","Sent with":"أُرسل بـ","Dropped by":"أسقطه","11, 0 (time exceeded)":"11، 0 (انتهى الوقت)","echo request":"طلب صدى","expires at the first router":"ينتهي عند الموجّه الأول","type 11 · from 192.168.1.1":"النوع 11 · من 192.168.1.1","quotes the dropped header":"يقتبس الترويسة المُسقطة","The next router answers":"الموجّه التالي يجيب","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"مع «-i 2»، يُنقص الموجّه المنزلي TTL إلى 1 ويمرّر الحزمة. فيُنقصها أول موجّه لدى مزوّد الإنترنت إلى 0 ويُبلغ من 198.51.100.1. ويترجم الموجّه المنزلي التقرير للحاسوب المحمول كأي رد.","ISP router 198.51.100.1":"موجّه المزوّد 198.51.100.1","expires at the second router":"ينتهي عند الموجّه الثاني","type 11 · from 198.51.100.1":"النوع 11 · من 198.51.100.1","That’s Traceroute":"هذا هو Traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1، 2، 3 … حتى يصل","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"يؤتمت tracert ذلك: يرفع TTL بواحد كل مرة، ويرسل ثلاثة مسابير لكل قفزة ويسرد من يُبلغ. وتعمل القفزات من 3 إلى 12 بالطريقة نفسها، ومع TTL 13 يصل الطلب أخيرًا إلى الخادم، فيرد بشكل عادي.","12 routers, then the server":"12 موجّهًا، ثم الخادم","Per hop":"لكل قفزة","3 probes":"3 مسابير","On Linux":"في Linux","traceroute sends UDP":"يرسل traceroute حزم UDP","enough hops to arrive":"قفزات كافية للوصول","the server itself answers":"الخادم نفسه يجيب","end of the route":"نهاية المسار",Unreachable:"تعذّر الوصول","Nothing listening on that port":"لا شيء يستمع على ذلك المنفذ","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"يرسل تطبيق مخطط بيانات UDP إلى المنفذ 9999، حيث لا شيء يستمع. ولا يستطيع الخادم تسليمه، فيرد برسالة Destination Unreachable، الرمز 3 (تعذّر الوصول إلى المنفذ)، مقتبسًا بداية مخطط البيانات. وكثير من جدران الحماية تُسقط هذه الحزم بصمت بدلًا من ذلك.","3, 3 (port unreachable)":"3، 3 (تعذّر الوصول إلى المنفذ)","Other codes":"رموز أخرى","0 net, 1 host, 4 too big":"0 شبكة، 1 مضيف، 4 كبيرة جدًا",Firewalls:"جدران الحماية","Often silent instead":"غالبًا تصمت بدلًا من ذلك","to port 9999":"إلى المنفذ 9999","nothing listening there":"لا شيء يستمع هناك","type 3 · code 3":"النوع 3 · الرمز 3","port unreachable":"تعذّر الوصول إلى المنفذ","ICMP · Echo request":"ICMP · طلب صدى",Code:"الرمز","Covers the whole ICMP message.":"يغطي رسالة ICMP كلها.",Identifier:"المعرّف","Matches replies to this ping program.":"يربط الردود ببرنامج ping هذا.","Windows counts up across every ping it sends.":"يزيد Windows العدّاد مع كل ping يرسله.","Windows ping’s filler: the alphabet, a to w, then again.":"حشو ping في Windows: الأبجدية، من a إلى w، ثم من جديد.","ICMP · Echo reply":"ICMP · رد صدى","Sent back exactly as it came.":"يُعاد كما جاء تمامًا.","ICMP · Time exceeded (TTL reached 0)":"ICMP · انتهى الوقت (بلغ TTL الصفر)","Time exceeded (TTL reached 0)":"انتهى الوقت (بلغ TTL الصفر)",Unused:"غير مستخدم","Original packet":"الحزمة الأصلية","Its source, destination":"مصدرها، وجهتها","its IP header and first 8 bytes (28 bytes)":"ترويسة IP الخاصة بها وأول 8 بايت (28 بايت)","App data":"بيانات التطبيق","What the app sent; nothing on the server is listening for it.":"ما أرسله التطبيق؛ لا شيء على الخادم يستمع له.","ICMP · Destination unreachable (port unreachable)":"ICMP · تعذّر الوصول إلى الوجهة (تعذّر الوصول إلى المنفذ)","Destination unreachable (port unreachable)":"تعذّر الوصول إلى الوجهة (تعذّر الوصول إلى المنفذ)","Sending Email":"إرسال البريد","SMTP command":"أمر SMTP","SMTP reply":"رد SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"ينقل SMTP البريد الإلكتروني: من تطبيق البريد لديك إلى خادم مزوّدك، ومن ذلك الخادم إلى خادم المستلم. وهو محادثة من أوامر نصية قصيرة، يُجاب كل منها برمز رد من ثلاثة أرقام. أما قراءة البريد فمهمة أخرى، تتم عبر IMAP أو POP3.","465/587 submit, 25 relay":"465/587 للإرسال، 25 للترحيل","TCP, usually with TLS":"TCP، عادةً مع TLS",Commands:"الأوامر",Replies:"الردود","2xx ok, 3xx go on, 4/5xx error":"2xx نجاح، 3xx تابع، 4/5xx خطأ","Mail delivered":"تم تسليم البريد","Two hops, one message":"قفزتان، ورسالة واحدة","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"سلّم تطبيق أليس الرسالة إلى مزوّدها عبر اتصال مشفّر بعد تسجيل الدخول. ووجد المزوّد خادم بريد بوب في DNS ورحّلها إليه، بعد ترقية ذلك الاتصال إلى TLS. وهي الآن تنتظر في صندوق بريد بوب إلى أن يقرأها عبر IMAP أو POP3.","Laptop → provider → Bob’s":"الحاسوب المحمول ← المزوّد ← خادم بوب",Submission:"الإرسال","Port 465, TLS, login":"المنفذ 465، TLS، تسجيل الدخول",Relay:"الترحيل","Port 25, STARTTLS":"المنفذ 25، STARTTLS","Checks at Bob’s":"الفحوص لدى بوب","Connect Securely":"الاتصال الآمن","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"تضغط أليس «إرسال». فيتصل تطبيق البريد لديها بخادم الإرسال لدى مزوّدها، smtp.example.com، على المنفذ 465. وعلى هذا المنفذ يبدأ TLS فورًا، لذا تكون محادثة SMTP كلها مشفّرة، بما فيها كلمة مرورها.","TLS from the start":"TLS من البداية","SMTP inside TLS":"SMTP داخل TLS","Greeting & Login":"التحية وتسجيل الدخول","EHLO, then AUTH":"EHLO، ثم AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"يحيّي الخادم بالرمز 220. يقول التطبيق EHLO فيسرد الخادم ما يدعمه، ومنه AUTH. ويسجّل التطبيق الدخول بـ AUTH PLAIN (اسم المستخدم وكلمة المرور، بترميز base64) فيتلقى 235: تمت المصادقة.",Greeting:"التحية",Capabilities:"القدرات","Login result":"نتيجة تسجيل الدخول","user and password, base64":"المستخدم وكلمة المرور، base64","Send the Message":"إرسال الرسالة","Envelope, then content":"المظروف، ثم المحتوى","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM وRCPT TO هما المظروف: المرسل والمستلم. ويتيح PIPELINING للأوامر الثلاثة مشاركة حزمة واحدة. وبعد 354 تأتي الرسالة، وتنتهي بسطر لا يحوي إلا نقطة.",Envelope:"المظروف","Content ends":"نهاية المحتوى","A line with only “.”":"سطر لا يحوي إلا «.»",Result:"النتيجة","… message …":"… الرسالة …","Find Bob’s Server":"العثور على خادم بوب","An MX lookup in DNS":"بحث عن MX في DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"على مزوّد أليس الآن أن يسلّم إلى example.org. فيسأل DNS عن سجل MX لذلك النطاق، الذي يسمّي الخادم الذي يقبل بريده، ثم يبحث عن عنوان ذلك الخادم.","MX record":"سجل MX","Asked by":"السائل","Alice’s provider":"مزوّد أليس","Server to Server":"من خادم إلى خادم","Port 25, upgraded with STARTTLS":"المنفذ 25، مع الترقية عبر STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"يتصل المزوّد بـ mx.example.org على المنفذ 25. تبدأ هذه المحادثة بنص غير مشفّر: تُعلن التحية ورد EHLO عن STARTTLS، فيطلبه المزوّد، ويتلقى 220 وينتقل الطرفان إلى TLS.","Starts as":"يبدأ بـ","Plain text":"نص غير مشفّر",Upgrade:"الترقية",Deliver:"التسليم","The same transaction again":"المعاملة نفسها مرة أخرى","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"بعد تشغيل TLS، يكرر المزوّد EHLO، ثم المظروف والرسالة، وقد أُضيف إليها الآن توقيع DKIM وترويسة Received. ويتحقق خادم بوب من SPF وDKIM وDMARC ويقبلها.","Login needed":"يلزم تسجيل الدخول","No (server to server)":"لا (من خادم إلى خادم)","1,316 bytes (signed)":"1,316 بايت (موقّعة)","Server Hello + encrypted handshake, 2 segments":"Server Hello + مصافحة مشفّرة، مقطعان","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 القدرات (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (بيانات الاعتماد)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (دفعة واحدة)","Message (316 bytes), then “.”":"الرسالة (316 بايت)، ثم «.»","250 capabilities (PIPELINING, STARTTLS …)":"250 القدرات (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 القدرات (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"الرسالة (1,316 بايت)، ثم «.»","What this client supports. Its exact contents vary from client to client; this is an example.":"ما يدعمه هذا العميل. وتختلف محتوياته الدقيقة من عميل إلى آخر؛ وهذا مثال.","up to 512 bytes":"حتى 512 بايت","The server’s choices and its key share.":"اختيارات الخادم وحصة مفتاحه.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions، Certificate (السلسلة)، Certificate Verify (التوقيع)، Finished","Alice’s message (316 bytes), then a line holding only “.”":"رسالة أليس (316 بايت)، ثم سطر لا يحوي إلا «.»","example.org, type MX, class IN":"example.org، النوع MX، الفئة IN","mx.example.org, type A, class IN":"mx.example.org، النوع A، الفئة IN",Timestamps:"الطوابع الزمنية","Used to measure round trips; both sides offered them.":"تُستخدم لقياس الرحلات ذهابًا وإيابًا؛ وقد عرضها الطرفان.","The signed message (1,316 bytes), then a line holding only “.”":"الرسالة الموقّعة (1,316 بايت)، ثم سطر لا يحوي إلا «.»","Downloading Email":"تنزيل البريد","POP3 command":"أمر POP3","POP3 reply":"رد POP3","Post Office Protocol, version 3":"بروتوكول مكتب البريد، الإصدار 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"يتيح POP3 لتطبيق البريد تنزيل الرسائل من صندوق بريد على خادم. وقد صُمّم لجهاز واحد يجلب البريد ثم يحذفه من الخادم. الأوامر كلمات قصيرة، وكل رد يبدأ بـ +OK أو -ERR.",Model:"النموذج","Download, then delete":"التنزيل ثم الحذف","Mail downloaded":"تم تنزيل البريد","And gone from the server":"وزال من الخادم","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"سجّل تطبيق بوب الدخول، ورأى رسالتين، فنزّل الأولى وحذفها، ونفّذ الخادم الحذف عند QUIT. وتلك الرسالة موجودة الآن على هذا الحاسوب المحمول وحده، ولهذا يناسب POP3 جهازًا واحدًا ويناسب IMAP عدة أجهزة.","2 waiting, 1 downloaded":"2 في الانتظار، 1 نُزّلت",Deleted:"الحذف","At QUIT (UPDATE state)":"عند QUIT (حالة UPDATE)","Best for":"الأنسب لـ","A single device":"جهاز واحد","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"يتصل تطبيق بريد بوب بـ pop.example.org على المنفذ 995، حيث يبدأ TLS فورًا. وداخله، يحيّي الخادم بـ +OK. (أما على المنفذ 110 فتبدأ الجلسة بنص غير مشفّر وتُرقّى بالأمر STLS.)","USER, then PASS":"USER، ثم PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"يرسل التطبيق اسم المستخدم بالأمر USER وكلمة المرور بالأمر PASS. ويتلقى كل أمر +OK خاصًا به. ولأن الجلسة داخل TLS، لا يمكن قراءة كلمة المرور في الطريق.","Protected by":"محمي بـ","Check the Mailbox":"فحص صندوق البريد","STAT and LIST":"STAT وLIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"يعيد STAT عدد الرسائل وحجمها الإجمالي: 2 رسالة، 5120 بايت. ويعطي LIST رقم كل رسالة وحجمها، وينتهي بسطر لا يحوي إلا نقطة.","Message 1":"الرسالة 1","Message 2":"الرسالة 2",Download:"التنزيل","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"يطلب RETR 1 الرسالة الأولى. فيجيب الخادم بـ +OK مع حجمها، ثم الرسالة ونقطة ختامية: 1904 بايت إضافةً إلى سطر الرد، في مقطعَي TCP.",Command:"الأمر","Delete & Quit":"الحذف والخروج","Deleted only at QUIT":"لا يُحذف إلا عند QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"لا يفعل DELE 1 سوى وسم الرسالة. ويحذفها الخادم حين يقول التطبيق QUIT: فلو انقطع الاتصال قبل ذلك، لما حُذف شيء. وتعرض تطبيقات كثيرة خيار «الإبقاء على نسخة في الخادم»، الذي يتخطى DELE.","Marks message 1":"يَسِم الرسالة 1",Removed:"أُزيلت",Option:"الخيار","Leave a copy on server":"الإبقاء على نسخة في الخادم","PASS (password)":"PASS (كلمة المرور)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets، الرسالة، «.» (مقطعان)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets، الرسالة ذات 1,904 بايت، ثم سطر لا يحوي إلا «.»","Mail That Stays in Sync":"بريد يبقى متزامنًا","IMAP command":"أمر IMAP","IMAP response":"استجابة IMAP","Internet Message Access Protocol":"بروتوكول الوصول إلى رسائل الإنترنت","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"يتيح IMAP لتطبيقات البريد العمل مع صندوق بريد يبقى على الخادم. وتُحفظ هناك المجلدات وعلامات القراءة والتمييز وعمليات الحذف، لذا يرى الهاتف والحاسوب المحمول وبريد الويب الصندوق نفسه. ويستطيع الخادم أيضًا إخبار التطبيق بالبريد الجديد فور وصوله.","Mail stays on the server":"البريد يبقى على الخادم",Syncs:"يزامن","Folders and flags":"المجلدات والعلامات","Mailbox in sync":"صندوق البريد متزامن","Read once, read everywhere":"تُقرأ مرة، فتُقرأ في كل مكان","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"فتح تطبيق بوب صندوق الوارد لديه، وقرأ رسالة، فوُسمت بـ \\Seen على الخادم لكل أجهزته، ثم انتظر بأمر IDLE حتى أعلن الخادم عن بريد جديد. لم يُحذف شيء: فالخادم ما يزال يحتفظ بكل شيء.","2, then 3 (new mail)":"2، ثم 3 (بريد جديد)","Read mark":"علامة القراءة","\\Seen, stored on server":"\\Seen، محفوظة على الخادم","New mail":"البريد الجديد","Pushed during IDLE":"يُدفع أثناء IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"يتصل تطبيق بوب بـ imap.example.org على المنفذ 993، حيث يبدأ TLS فورًا. ويحيّي الخادم بسطر «* OK» بلا وسم، يسرد أيضًا قدراته، مثل IDLE.","Commands carry tags":"الأوامر تحمل وسومًا","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"يبدأ كل أمر بوسم يختاره التطبيق، مثل a1، ويُنهي الخادم إجابته بالوسم نفسه. وبهذا يمكن أن تكون عدة أوامر قيد التنفيذ ويُطابَق كل رد مع أمره. أما الأسطر التي تبدأ بـ * فهي بيانات بلا وسم.",Tags:"الوسوم","Match replies to commands":"تطابق الردود مع الأوامر","Open the Inbox":"فتح صندوق الوارد","SELECT a folder":"SELECT لمجلد","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"يفتح SELECT INBOX المجلد. ويُبلغ الخادم عن عدد الرسائل، والعلامات التي يدعمها، وأول رسالة غير مقروءة، ثم يؤكد أن المجلد مفتوح للقراءة والكتابة.","First unread":"أول غير مقروءة",Access:"الوصول","Read a Message":"قراءة رسالة","FETCH, and the \\Seen flag":"FETCH، وعلامة \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"ينزّل FETCH 2 BODY[] الرسالة 2 (ثلاثة مقاطع TCP). وهذا يضبط علامة \\Seen لها على الخادم، فتظهر مقروءة على هاتف بوب أيضًا، وتبقى الرسالة هناك.","Flag set":"العلامة المضبوطة","\\Seen (on the server)":"\\Seen (على الخادم)","Wait for New Mail":"انتظار بريد جديد","IDLE: the server pushes":"IDLE: الخادم يدفع","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"يقول IDLE للخادم «أخبرني حين يتغير شيء». وبعد نحو 42 ثانية تصل رسالة أليس فيدفع الخادم «* 3 EXISTS» فورًا. ويُنهي التطبيق IDLE بـ DONE ويستطيع جلب البريد الجديد.","Server says":"الخادم يقول","* 3 EXISTS (new mail)":"* 3 EXISTS (بريد جديد)","Ended by":"يُنهى بـ","a1 LOGIN (user and password)":"a1 LOGIN (المستخدم وكلمة المرور)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}، الرسالة ذات 3,216 بايت، ثم a3 OK FETCH completed","Transferring Files":"نقل الملفات","FTP command":"أمر FTP","FTP reply":"رد FTP","File data":"بيانات الملف","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"ينقل FTP الملفات بين عميل وخادم. وهو غير مألوف في استخدامه اتصالين من TCP: واحد للأوامر والردود، وآخر جديد لكل ملف أو قائمة. ويعود إلى أوائل سبعينيات القرن الماضي، ويرسل كل شيء، بما في ذلك كلمات المرور، نصًا غير مشفّر.","21 control, data varies":"21 للتحكم، والبيانات متغيّر",Connections:"الاتصالات","Control + one per transfer":"التحكم + واحد لكل نقل",Encryption:"التشفير","None (plain text)":"لا يوجد (نص غير مشفّر)","Safer options":"بدائل أكثر أمانًا","File downloaded":"تم تنزيل الملف","Two connections, no encryption":"اتصالان، بلا تشفير","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"مرّت الأوامر عبر اتصال التحكم، والملف عبر اتصال بيانات خاص به، وكان إغلاق ذلك الاتصال علامة نهاية الملف. وكان بإمكان أي أحد على المسار قراءة كلمة المرور والملف، ولهذا يُستخدم اليوم SFTP أو FTPS.","2 (control + data)":"2 (تحكم + بيانات)",File:"الملف","4,000 bytes, 3 segments":"4,000 بايت، 3 مقاطع",Password:"كلمة المرور","Sent in plain text":"أُرسلت نصًا غير مشفّر","Use instead":"استخدم بدلًا منه","Control Connection":"اتصال التحكم","Port 21, plain text":"المنفذ 21، نص غير مشفّر","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"يفتح تطبيق FTP اتصال TCP بـ ftp.example.com على المنفذ 21. ويحمل اتصال التحكم هذا الأوامر والردود طوال الجلسة. ويحيّي الخادم بـ 220. وكما في SMTP، يبدأ كل رد برمز من ثلاثة أرقام.","USER and PASS, readable by anyone":"USER وPASS، يقرؤهما أي أحد","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"يرسل التطبيق USER، فيطلب الخادم كلمة المرور بالرمز 331، ويرسلها PASS. لا شيء مشفّر، لذا يعبر اسم المستخدم وكلمة المرور كل شبكة على الطريق نصًا مقروءًا.","Visible to":"ظاهر لـ","Anyone on the path":"أي أحد على المسار","Passive Mode":"الوضع السلبي","The server names a data port":"الخادم يسمّي منفذ بيانات","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"يطلب TYPE I نسخة ثنائية مطابقة بايتًا ببايت. ويطلب PASV من الخادم فتح منفذ لاتصال البيانات. ويرمّز الرد العنوان والمنفذ في ستة أرقام: 195 × 256 + 149 = المنفذ 50069. ويتصل الحاسوب المحمول إلى الخارج، وهذا يعمل عبر NAT.","Data port":"منفذ البيانات","Active mode":"الوضع النشط","Server dials in: NAT blocks":"الخادم يتصل إلى الداخل: NAT يمنعه","Data Connection":"اتصال البيانات","A second TCP connection":"اتصال TCP ثانٍ","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"يفتح التطبيق اتصال TCP ثانيًا، إلى المنفذ 50069، ويطلب الملف عبر اتصال التحكم بالأمر RETR. فيجيب الخادم هناك بـ 150 ويبدأ إرسال الملف عبر الاتصال الجديد.","Data to":"البيانات إلى","The File Arrives":"وصول الملف","Closing the connection ends it":"إغلاق الاتصال يُنهيه","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"تصل الـ 4,000 بايت في 3 مقاطع TCP. لا يرسل FTP أي علامة طول داخل البيانات نفسها: بل يُغلق الخادم اتصال البيانات ليعلن نهاية الملف. وبعد أن يُقرّ الحاسوب المحمول بكل شيء، يؤكد الخادم بالرمز 226 على اتصال التحكم.","End of file":"نهاية الملف","Data connection closed":"أُغلق اتصال البيانات","4,000 bytes, readable by anyone":"4,000 بايت، يقرؤها أي أحد","end of file:":"نهاية الملف:","data connection closed":"أُغلق اتصال البيانات",Quit:"الخروج","Close the control connection":"إغلاق اتصال التحكم","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"يُنهي QUIT الجلسة ويودّع الخادم بالرمز 221. ولأي شيء حساس، يؤدي SFTP (بروتوكول مختلف يعمل فوق SSH) أو FTPS (FTP داخل TLS) المهمة نفسها مع التشفير.","Encrypted cousins":"أقارب مشفّرون","FTP data":"بيانات FTP","The file itself, unencrypted: anyone on the path could read it.":"الملف نفسه، غير مشفّر: كان بإمكان أي أحد على المسار قراءته.","Secure Remote Login":"تسجيل دخول آمن عن بُعد","Plain setup":"إعداد غير مشفّر","From laptop":"من الحاسوب المحمول","From server":"من الخادم","Some packets not shown":"بعض الحزم غير معروضة","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"يمنحك SSH اتصالًا مشفّرًا وموثّقًا بحاسوب آخر، لتشغيل الأوامر عليه، أو نسخ الملفات (SFTP، scp) أو نقل اتصالات أخرى. ويثبت الخادم هويته بمفتاح المضيف؛ وتثبت أنت هويتك بزوج مفاتيح أو بكلمة مرور.","Server proves":"الخادم يثبت","Host key (known_hosts)":"مفتاح المضيف (known_hosts)","You prove":"أنت تثبت","Key pair or password":"زوج مفاتيح أو كلمة مرور","Logged in securely":"تم تسجيل الدخول بأمان","Encrypted from the key exchange on":"مشفّر من تبادل المفاتيح فصاعدًا","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"اتفق الطرفان على الخوارزميات، وبنيا مفاتيح مشتركة بتبادل هجين مقاوم للحوسبة الكمّية، وأثبت الخادم هويته بمفتاح المضيف. وأثبتت أليس هويتها بالتوقيع بمفتاح خاص لم يغادر الحاسوب المحمول قط، ثم كتبت أمرًا، بحزمة واحدة لكل ضغطة مفتاح.",Login:"تسجيل الدخول","Ed25519 key, no password":"مفتاح Ed25519، بلا كلمة مرور","Say Hello":"التحية","Versions, in plain text":"الإصدارات، بنص غير مشفّر","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"تشغّل أليس «ssh alice@server.example.com». وبعد مصافحة TCP على المنفذ 22، يرسل كل طرف سطرًا واحدًا من نص غير مشفّر يذكر إصدار بروتوكول SSH (2.0) وبرنامجه. وكل ما عدا ذلك في SSH ثنائي.","Agree on Algorithms":"الاتفاق على الخوارزميات","KEXINIT lists, first match wins":"قوائم KEXINIT، وأول تطابق يفوز","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"يرسل كل طرف KEXINIT يسرد كل خوارزمية يدعمها، بترتيب الأفضلية، لتبادل المفاتيح ومفاتيح المضيف والتشفير والسلامة والضغط. وفي كل فئة، تُختار أول خوارزمية في قائمة الحاسوب المحمول يدعمها الخادم أيضًا.","Host key":"مفتاح المضيف","server’s algorithm lists":"قوائم خوارزميات الخادم","in order of preference":"بترتيب الأفضلية","laptop’s algorithm lists":"قوائم خوارزميات الحاسوب المحمول","Key Exchange":"تبادل المفاتيح","Shared keys, and a host key check":"مفاتيح مشتركة، وفحص مفتاح المضيف","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"يرسل الحاسوب المحمول نصيبه من تبادل هجين: مفتاح Streamlined NTRU Prime، اختير لمقاومة الحواسيب الكمّية المستقبلية، إضافةً إلى مفتاح X25519. ويجيب الخادم بنصيبه ومفتاح المضيف وتوقيع على التبادل. ويشغّل NEWKEYS التشفير.",Hybrid:"هجين","Matches known_hosts":"يطابق known_hosts","First visit":"الزيارة الأولى","ssh asks you to confirm":"يطلب منك ssh التأكيد","public keys":"المفاتيح العامة","its half, its host key":"نصيبه، مفتاح المضيف","and a signature":"وتوقيع","Log In with a Key":"تسجيل الدخول بمفتاح","Sign, don’t send a secret":"وقّع، ولا ترسل سرًا","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"يسرد الخادم طرائق تسجيل الدخول التي يقبلها. يعرض الحاسوب المحمول المفتاح العام لأليس، فيقول الخادم إنه سيقبله. ثم يوقّع الحاسوب المحمول هذه الجلسة بالمفتاح الخاص، الذي لا يغادر الحاسوب المحمول أبدًا. ويتحقق الخادم من التوقيع مقابل authorized_keys.",Methods:"الطرائق","Ed25519, private stays here":"Ed25519، والمفتاح الخاص يبقى هنا","Checked with":"يُتحقق منه بـ","alice’s public key":"المفتاح العام لـ alice","would you accept it?":"هل تقبله؟","yes, that key":"نعم، ذلك المفتاح","is in authorized_keys":"موجود في authorized_keys","same key, plus a signature":"المفتاح نفسه، مع توقيع","made with the private key":"أُنشئ بالمفتاح الخاص","logged in":"تم تسجيل الدخول","Open a Session":"فتح جلسة","Channels inside one connection":"قنوات داخل اتصال واحد","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"يمكن لاتصال SSH واحد أن يحمل قنوات كثيرة: صدفة أوامر، ونقل ملفات، ومنافذ محوّلة. يفتح الحاسوب المحمول قناة جلسة، ثم يطلب طرفية وصدفة (غير معروض)، فيرسل الخادم نص الترحيب ومحثّ الأوامر.",Channel:"القناة",session:"session","Then asks for":"ثم يطلب","A terminal and a shell":"طرفية وصدفة","Also possible":"ممكن أيضًا","SFTP, port forwarding":"SFTP، تحويل المنافذ","open a channel:":"فتح قناة:","channel open":"فُتحت القناة","Type a Command":"كتابة أمر","Every key is a packet":"كل ضغطة مفتاح حزمة","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"تكتب أليس pwd. تخرج كل ضغطة مفتاح فورًا في حزمتها المشفّرة الخاصة، ويعيد الخادم الحرف ليُعرض (الصدى). ومنذ الإصدار 9.5، يرسل OpenSSH ضغطات المفاتيح على إيقاع 20 ms ويضيف حزمًا وهمية، فيصعب استنتاج إيقاع الكتابة من التوقيت.","Per key":"لكل ضغطة","1 packet, 90 bytes":"1 حزمة، 90 بايت",Echo:"الصدى","Sent back by the server":"يعيده الخادم",Timing:"التوقيت","20 ms beat plus decoys":"إيقاع 20 ms مع حزم وهمية","Enter key":"مفتاح Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"العميل: KEX_ECDH_INIT (المفاتيح العامة sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"الخادم: KEX_ECDH_REPLY (مفتاح المضيف، نصيبه، التوقيع)","Encrypted (len=44): service request, ssh-userauth":"مشفّر (len=44): طلب خدمة، ssh-userauth","Encrypted (len=44): service accept":"مشفّر (len=44): قبول الخدمة","Encrypted (len=68): login with method none":"مشفّر (len=68): تسجيل دخول بالطريقة none","Encrypted (len=52): try publickey,password":"مشفّر (len=52): جرّب publickey,password","Encrypted (len=140): offer public key":"مشفّر (len=140): عرض المفتاح العام","Encrypted (len=100): public key OK":"مشفّر (len=100): المفتاح العام مقبول","Encrypted (len=308): public key + signature":"مشفّر (len=308): المفتاح العام + توقيع","Encrypted (len=28): login success":"مشفّر (len=28): نجح تسجيل الدخول","Encrypted (len=52): channel open: session":"مشفّر (len=52): فتح قناة: session","Encrypted (len=44): channel open confirmed":"مشفّر (len=44): تأكيد فتح القناة","Encrypted (len=36): keystroke":"مشفّر (len=36): ضغطة مفتاح","Encrypted (len=36): echo":"مشفّر (len=36): صدى","Encrypted (len=36): keystroke (Enter)":"مشفّر (len=36): ضغطة مفتاح (Enter)","Encrypted (len=132): output and a new prompt":"مشفّر (len=132): المخرجات ومحثّ جديد","Packet length":"طول الحزمة","Bytes after this field.":"البايتات بعد هذا الحقل.","Padding length":"طول الحشو","Random padding brings the packet to a multiple of 8 bytes.":"يجعل الحشو العشوائي طول الحزمة من مضاعفات 8 بايت.",Cookie:"Cookie","Host keys":"مفاتيح المضيف","Ciphers, out":"التشفير، صادر","Ciphers, in":"التشفير، وارد","MACs, out":"MAC، صادر","Compression, out":"الضغط، صادر","Compression, in":"الضغط، وارد","Languages, out":"اللغات، صادر","Languages, in":"اللغات، وارد","First packet follows":"الحزمة الأولى تليه",Reserved:"محجوز","Public keys":"المفاتيح العامة","51 bytes: ssh-ed25519 public key":"51 بايت: المفتاح العام ssh-ed25519","Server’s half":"نصيب الخادم","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 بايت (نص sntrup761 المشفّر 1,039 + X25519 32)",Signature:"التوقيع","83 bytes: ssh-ed25519 signature over the exchange":"83 بايت: توقيع ssh-ed25519 على التبادل","From the next packet on, this side encrypts.":"بدءًا من الحزمة التالية، يشفّر هذا الطرف.","SSH · encrypted packet":"SSH · حزمة مشفّرة","Encrypted packet":"حزمة مشفّرة","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"مع chacha20-poly1305 حتى الطول مشفّر؛ ووسم من 16 بايت في النهاية يكشف أي تغيير.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): المستخدم «alice»، الخدمة «ssh-connection»، الطريقة «none»","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): الطرائق التي يمكن المتابعة بها: «publickey,password»","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): الطريقة «publickey»، بلا توقيع، المفتاح العام ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): مفتاح ssh-ed25519 نفسه","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): الطريقة «publickey-hostbound-v00@openssh.com»، المفتاح، ومفتاح مضيف الخادم وتوقيع","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): «session»، القناة 0، النافذة 2 MB، حزم حتى 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): القناة 0 مفتوحة","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، «p»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، «p»، أُعيد ليُعرض","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، «w»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، «w»، أُعيد ليُعرض","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، «d»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، «d»، أُعيد ليُعرض","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 1 بايت، محرف إرجاع العربة (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94)، القناة 0: 94 بايت: سطر جديد، ورموز الطرفية من الصدفة، و«/home/alice»، والمحثّ الملوّن","Encryption Explained":"شرح التشفير","From browser":"من المتصفح","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"يضع TLS قناة آمنة فوق TCP. فيثبت هوية الخادم بشهادة، ويتفق على مفاتيح جديدة، ثم يشفّر كل ما يُرسل ويوثّقه. ويعمل داخله HTTPS والبريد الآمن وبروتوكولات كثيرة أخرى. وكان SSL اسم سلفه.",Sits:"موقعه","Between TCP and the app":"بين TCP والتطبيق","OSI layer":"طبقة OSI","Often placed at 6":"يوضع غالبًا في 6",Current:"الحالي",Retired:"المُلغاة","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 و3، TLS 1.0 و1.1","The app’s own (443, 993 …)":"منفذ التطبيق نفسه (443، 993 …)","Secure from start to finish":"آمن من البداية إلى النهاية","One round trip to set up":"رحلة واحدة ذهابًا وإيابًا للإعداد","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"في رحلة واحدة ذهابًا وإيابًا تم الاتفاق على إصدار وخوارزمية تشفير ومفتاح هجين مقاوم للحوسبة الكمّية. وأثبتت سلسلة الشهادات هوية الخادم، وكان كل بايت بعد Server Hello مشفّرًا وموثّقًا، حتى close_notify. اضغط «مرة أخرى» لمشاهدته من جديد.","1 round trip":"رحلة واحدة ذهابًا وإيابًا","Everything the browser supports":"كل ما يدعمه المتصفح","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"بعد مصافحة TCP يسرد المتصفح ما يستطيعه: إصدارات TLS، ومجموعات التشفير، وحصص المفاتيح للمجموعات التي يتوقعها، ومنها المجموعة الهجينة المقاومة للحوسبة الكمّية X25519MLKEM768. ويسمّي أيضًا الموقع (SNI) والبروتوكولات التي يتحدثها (ALPN).",Versions:"الإصدارات","versions, ciphers, key shares":"الإصدارات، خوارزميات التشفير، حصص المفاتيح","Choices made, keys computed":"اتُّخذت الخيارات، وحُسبت المفاتيح","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"يختار الخادم TLS 1.3 ومجموعة التشفير والمجموعة الهجينة، ويرسل حصة مفتاحه. ومن الحصتين يحسب الطرفان السر نفسه دون أن يعبر الشبكة قط. وكل ما بعد هذه الرسالة مشفّر.",Group:"المجموعة","From here on":"من هنا فصاعدًا","its key share":"حصة مفتاحه",Certificate:"الشهادة","Who the server is, proven":"هوية الخادم، مُثبتة","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"وتستمر دفعة الرسائل، مشفّرة الآن: البروتوكول المختار (http/1.1)، وسلسلة الشهادات، وتوقيع بالمفتاح الخاص للشهادة، وFinished.",Chain:"السلسلة","Site → intermediate → root":"الموقع ← الوسيطة ← الجذر","Proves the private key":"يثبت امتلاك المفتاح الخاص",Checked:"ما يُفحص","Name, dates, trusted root":"الاسم، التواريخ، جذر موثوق","encrypted: http/1.1, certificates,":"مشفّر: http/1.1، الشهادات،","signature, Finished":"التوقيع، Finished","One round trip, then data":"رحلة واحدة، ثم البيانات","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"يرسل المتصفح Finished الخاص به: قيمة تحقق على كل ما قاله الطرفان، مفتاحها السر الجديد، فيظهر أي عبث برسائل hello. ويحتاج TLS 1.3 إلى رحلة واحدة ذهابًا وإيابًا قبل تدفق البيانات؛ وكان TLS 1.2 يحتاج إلى رحلتين.",Covers:"يغطي","The whole handshake":"المصافحة كلها","For old middleboxes":"من أجل الأجهزة الوسيطة القديمة","check value over":"قيمة تحقق تشمل","the whole handshake":"المصافحة كلها","Encrypted Data":"البيانات المشفّرة","Records, tags and tickets":"سجلات ووسوم وتذاكر","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"ينتقل HTTP الآن في سجلات مشفّرة، لكلٍّ منها وسم من 16 بايت يكشف أي تغيير. ويرسل الخادم أيضًا تذكرتي جلسة: في المرة القادمة يستطيع المتصفح الاستئناف بإحداهما وتخطي الشهادة.","Per record":"لكل سجل","22 bytes of overhead":"22 بايت إضافية","2, for resuming later":"2، للاستئناف لاحقًا",Visible:"ما يظهر","IPs, SNI, sizes, timing":"عناوين IP، SNI، الأحجام، التوقيت","2 session tickets":"تذكرتا جلسة","for resuming later":"للاستئناف لاحقًا",Closing:"الإغلاق","close_notify, then TCP":"close_notify، ثم TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"بعد 75 ثانية من الخمول يُغلق الخادم الاتصال. فيرسل أولًا تنبيه close_notify، مشفّرًا ككل شيء آخر، ليعرف المتصفح أن البيانات انتهت عمدًا ولم يقطعها مهاجم. ثم يُغلق TCP كالمعتاد.",Alert:"التنبيه","Shows nothing was cut off":"يُظهر أن شيئًا لم يُقطع","TCP FIN from both sides":"TCP FIN من الطرفين","alert: close_notify":"تنبيه: close_notify",encrypted:"مشفّر","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello، Change Cipher Spec (+ مشفّر)","Encrypted handshake (continued)":"مصافحة مشفّرة (تابع)","Encrypted handshake (certificate, verify, Finished)":"مصافحة مشفّرة (الشهادة، التحقق، Finished)","Application Data (inside: close_notify alert)":"Application Data (في الداخل: تنبيه close_notify)","Alert: close_notify (the data ends here, on purpose)":"تنبيه: close_notify (البيانات تنتهي هنا، عمدًا)","No IP address":"بلا عنوان IP","192.168.1.1 · DHCP server":"192.168.1.1 · خادم DHCP"},i=(t,e,s,r,h)=>{const a=Number(t);return a===1?e:a===2?s:`${t} ${a%100>=3&&a%100<=10?r:h}`},o=t=>i(t,"مقطع واحد","مقطعان","مقاطع","مقطعًا"),n=t=>i(t,"سجل واحد","سجلان","سجلات","سجلًا"),T={strings:{...l,...c},patterns:[[/^([\d,]+) bytes$/,"$1 بايت"],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,"$1 · $2 بايت"],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,"$1، $2 بايت"],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,"$1 بايت: report.pdf، البايتات $2"],[/^(.+) h later$/,"بعد $1 ساعة"],[/^(.+) min later$/,"بعد $1 دقيقة"],[/^(.+) s later$/,"بعد $1 ثانية"],[/^(\S+) \(relative\)$/,"$1 (نسبي)"],[/^(\d+) \(ephemeral\)$/,"$1 (مؤقت)"],[/^(\d+) TCP segments$/,(t,e)=>`${o(e)} من TCP`],[/^(\d+) segments$/,(t,e)=>o(e)],[/^(.*), (\d+) segments$/,(t,e,s)=>`${e}، ${o(s)}`],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(t,e,s,r)=>`TLS 1.3 · ${n(e)} · البايتات ${s} من ${r}`],[/^TLS 1\.3 · (\d+) records?$/,(t,e)=>`TLS 1.3 · ${n(e)}`],[/^Ethernet padding · (\d+) bytes$/,"حشو إيثرنت · $1 بايت"],[/^(\d+) zero bytes, up to the 300-byte minimum$/,"$1 بايت صفري، حتى الحد الأدنى البالغ 300 بايت"],[/^(\d+) zero bytes$/,"$1 بايت صفري"],[/^(\d+) random bytes$/,"$1 بايت عشوائي"],[/^Seen as it leaves (.+)$/,"كما رُصدت عند خروجها من $1"],[/^Option (\d+)$/,"الخيار $1"],[/^value (\d+), echo (\d+)$/,"القيمة $1، الصدى $2"],[/^20 bytes, plus (\d+) of options\.$/,"20 بايت، إضافةً إلى $1 للخيارات."],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"يبدأ Windows من $1. ضُبطت هنا عمدًا على $2."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,e,s)=>s==="1"?`بدأت من ${e}؛ وأنقصها الموجّه الوحيد على الطريق بمقدار 1.`:`بدأت من ${e}؛ وأنقصها كل موجّه من الموجّهات الـ ${s} على الطريق بمقدار 1.`],[/^all (\d+) bytes of it$/,"جميع بايتاتها الـ $1"],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"الحزمة التي تسببت في ذلك، كما استلمها الجهاز المُبلِّغ (TTL $1)، ليعرف المرسل أي حزمة كانت."],[/^Port (\d+), TLS from the start$/,"المنفذ $1، مع TLS من البداية"],[/^(\d+), TLS from the start$/,"$1، مع TLS من البداية"]],post:d};export{T as default};
